// --- myns.FDb.part.Find
// Look up row by row id. Return NULL if out of range
inline myns::FPart* myns::part_Find(u64 t) {
    myns::FPart *retval = NULL;
    if (LIKELY(u64(t) < u64(_db.part_n))) {
        u64 x = t + 1;
        u64 bsr   = algo::u64_BitScanReverse(x);
        u64 base  = u64(1)<<bsr;
        u64 index = x-base;
        retval = &_db.part_lary[bsr][index];
    }
    return retval;
}

