// --- myns.MsgHeader_curs..Reset
inline void myns::MsgHeader_curs_Reset(myns::MsgHeader_curs& curs, algo::memptr buf) {
    curs.bytes = buf.elems;
    curs.limit = buf.n_elems;
    myns::MsgHeader *msg = NULL;
    int msglen = 0;
    if (curs.limit >= ssizeof(myns::MsgHeader)) {
        myns::MsgHeader *ptr = (myns::MsgHeader*)curs.bytes;
        msglen = i32((*ptr).length);
        if (msglen >= ssizeof(myns::MsgHeader) && curs.limit >= msglen) {
            msg = ptr;
        }
    }
    curs.msg = msg;
    curs.msglen = msglen;
}

// --- myns.MsgHeader_curs..Access
inline myns::MsgHeader*& myns::MsgHeader_curs_Access(myns::MsgHeader_curs& curs) {
    return curs.msg;
}

// --- myns.MsgHeader_curs..Next
inline void myns::MsgHeader_curs_Next(myns::MsgHeader_curs& curs) {
    curs.bytes += curs.msglen;
    curs.limit -= curs.msglen;
    myns::MsgHeader *msg = NULL;
    int msglen = 0;
    if (curs.limit >= ssizeof(myns::MsgHeader)) {
        myns::MsgHeader *ptr = (myns::MsgHeader*)curs.bytes;
        msglen = i32((*ptr).length);
        if (msglen >= ssizeof(myns::MsgHeader) && curs.limit >= msglen) {
            msg = ptr;
        }
    }
    curs.msg = msg;
    curs.msglen = msglen;
}

