// --- myns.NewOrderReqMsg.base.Castdown
// Check if myns::MsgHeader is an instance of NewOrderReqMsg by checking the type field
// If it is, return the pointer of target type.
// Additionally, check if the length field permits valid instance of NewOrderReqMsg.
// If not successful, quietly return NULL.
inline myns::NewOrderReqMsg* myns::NewOrderReqMsg_Castdown(myns::MsgHeader &hdr) {
    bool cond = hdr.type == (66);
    cond &= i32(hdr.length) >= ssizeof(myns::NewOrderReqMsg);
    return cond ? reinterpret_cast<myns::NewOrderReqMsg*>(&hdr) : NULL;
}

// --- myns.NewOrderReqMsg.base.Castbase
inline myns::MsgHeader& myns::Castbase(myns::NewOrderReqMsg& parent) {
    return reinterpret_cast<myns::MsgHeader&>(parent);
}

