// --- myns.Order..Init
// Set all fields to initial values.
inline void myns::Order_Init(myns::Order& order) {
    order.p_part = NULL;
    order.quantity = i32(0);
    order.filled = bool(false);
    order.order_next = (myns::Order*)-1; // (myns.FDb.order) not-in-tpool's freelist
    order.ind_order_next = (myns::Order*)-1; // (myns.FDb.ind_order) not-in-hash
    order.zd_order_next = (myns::Order*)-1; // (myns.FDb.zd_order) not-in-list
    order.zd_order_prev = NULL; // (myns.FDb.zd_order)
    order.zd_partorder_next = (myns::Order*)-1; // (myns.FPart.zd_partorder) not-in-list
    order.zd_partorder_prev = NULL; // (myns.FPart.zd_partorder)
}

